using System;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
public static class ValidateDeformableMud {
static Mesh Grid(){const int nx=80,nz=80;var v=new Vector3[(nx+1)*(nz+1)];var uv=new Vector2[v.Length];var t=new List<int>();for(int z=0;z<=nz;z++)for(int x=0;x<=nx;x++){int i=z*(nx+1)+x;v[i]=new Vector3((x-nx/2)*.10f,0,(z-nz/2)*.10f);uv[i]=new Vector2(x*.05f,z*.05f);if(x<nx&&z<nz){t.AddRange(new[]{i,i+nx+1,i+1,i+1,i+nx+1,i+nx+2});}}var m=new Mesh{name="TEMP dense mud fixture"};m.vertices=v;m.uv=uv;m.triangles=t.ToArray();m.RecalculateNormals();return m;}
static GameObject Soil(Mesh mesh,SoftGroundProfile profile,Vector3 p,string key){var go=new GameObject("TEMP local mud");go.transform.position=p;go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>();go.AddComponent<MeshCollider>().sharedMesh=mesh;var surface=go.AddComponent<ForestDrivingSurface>();surface.cover=ForestDrivingSurface.Cover.Mud;surface.forwardGrip=.4f;surface.lateralGrip=.4f;surface.rollingResistance=.045f;var soil=go.AddComponent<SoftGroundRuts>();soil.profile=profile;soil.fieldHalfSize=new Vector2(4,4);soil.BindPersistence(key);return go;}
public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var source=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var sourceBody=source.GetComponent<Rigidbody>();bool kinematic=sourceBody.isKinematic;var velocity=sourceBody.linearVelocity;var angular=sourceBody.angularVelocity;bool paused=EditorApplication.isPaused;var mode=Physics.simulationMode;GameObject ground=null,clone=null,restored=null,renderProbe=null;Mesh mesh=null;SoftGroundProfile profile=null;string report="";try{Physics.simulationMode=SimulationMode.Script;EditorApplication.isPaused=true;sourceBody.isKinematic=true;mesh=Grid();profile=ScriptableObject.CreateInstance<SoftGroundProfile>();var centre=new Vector3(30000,20,30000);string key="validation/"+Guid.NewGuid();ground=Soil(mesh,profile,centre,key);var soil=ground.GetComponent<SoftGroundRuts>();clone=UnityEngine.Object.Instantiate(source.gameObject,centre+Vector3.up*.65f,Quaternion.identity);var v=clone.GetComponent<VehiclePhysics>();var rb=clone.GetComponent<Rigidbody>();rb.isKinematic=false;v.externalControl=true;v.automaticSimulation=false;clone.GetComponent<VehiclePlayerInput>().enabled=false;clone.GetComponent<VehicleAudio>().enabled=false;v.SetInput(new VehicleControlInput{brake=1});Physics.SyncTransforms();Action step=()=>{v.Simulate(.01f);Physics.Simulate(.01f);v.SendMessage("LateUpdate");};for(int i=0;i<200;i++)step();float startY=rb.position.y;
rb.constraints=RigidbodyConstraints.FreezePositionX|RigidbodyConstraints.FreezePositionZ;v.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<650;i++){foreach(var binding in v.axles){if(binding.left.GetGroundHit(out var hit))SoftGroundRuts.Contact(hit.point,Vector3.forward,.285f,hit.force,12,1,.01f);}step();}soil.Commit();float leftDepth=soil.DepthAt(new Vector3(centre.x-.714f,20,centre.z-1.21f)),rightDepth=soil.DepthAt(new Vector3(centre.x+.714f,20,centre.z-1.21f));float tilt=Vector3.Angle(Vector3.up,clone.transform.up),sink=startY-rb.position.y;if(leftDepth<.12f||rightDepth>leftDepth-.08f||tilt<3||sink<.03f)throw new Exception("Asymmetric physical sinking missing L="+leftDepth+" R="+rightDepth+" tilt="+tilt+" sink="+sink);report+="left="+leftDepth.ToString("F3")+"m right="+rightDepth.ToString("F3")+"m; natural roll="+tilt.ToString("F1")+"deg, body sink="+sink.ToString("F3")+"m; ";
renderProbe=new GameObject("TEMP independent visible mesh ray");renderProbe.transform.position=ground.transform.position;var renderCollider=renderProbe.AddComponent<MeshCollider>();renderCollider.sharedMesh=ground.GetComponent<MeshFilter>().sharedMesh;var ray=new Ray(new Vector3(centre.x-.714f,25,centre.z-1.21f),Vector3.down);if(!renderCollider.Raycast(ray,out var visible,10)||!ground.GetComponent<MeshCollider>().Raycast(ray,out var physical,10)||Mathf.Abs(visible.point.y-physical.point.y)>.002f)throw new Exception("Visible/physical mesh mismatch");UnityEngine.Object.DestroyImmediate(renderProbe);renderProbe=null;
UnityEngine.Object.DestroyImmediate(clone);clone=null;UnityEngine.Object.DestroyImmediate(ground);ground=null;restored=Soil(mesh,profile,centre,key);var loaded=restored.GetComponent<SoftGroundRuts>();float reloaded=loaded.DepthAt(new Vector3(centre.x-.714f,20,centre.z-1.21f));if(Mathf.Abs(reloaded-leftDepth)>.001f)throw new Exception("Tracks lost after recreation");var offset=new Vector3(10000,0,10000);restored.transform.position-=offset;loaded.ShiftOrigin(offset);float shifted=loaded.DepthAt(new Vector3(centre.x-.714f,20,centre.z-1.21f)-offset);if(Mathf.Abs(shifted-leftDepth)>.001f)throw new Exception("Tracks lost at floating origin");report+="independent render/collision rays match; tracks survive recreation and origin shift; ";UnityEngine.Object.DestroyImmediate(restored);restored=null;
var p1=centre+Vector3.forward*20;ground=Soil(mesh,profile,p1,key+"/pressure");soil=ground.GetComponent<SoftGroundRuts>();Vector3 normal=p1+Vector3.left,soft=p1+Vector3.right;for(int i=0;i<250;i++){SoftGroundRuts.Contact(normal,Vector3.forward,.285f,5000,10,1,.01f);SoftGroundRuts.Contact(soft,Vector3.forward,.285f,5000,10,.7f,.01f);}soil.Commit();float normalDepth=soil.DepthAt(normal),softDepth=soil.DepthAt(soft);if(softDepth>=normalDepth*.85f||normalDepth>.381f)throw new Exception("Pressure does not reduce sink N="+normalDepth+" soft="+softDepth);report+="equal-load digging: road pressure="+normalDepth.ToString("F3")+"m, deflated="+softDepth.ToString("F3")+"m.";return "PASS DEFORMABLE MUD: "+report;
}finally{foreach(var go in new[]{ground,clone,restored,renderProbe})if(go!=null)UnityEngine.Object.DestroyImmediate(go);if(mesh!=null)UnityEngine.Object.DestroyImmediate(mesh);if(profile!=null)UnityEngine.Object.DestroyImmediate(profile);sourceBody.isKinematic=kinematic;if(!kinematic){sourceBody.linearVelocity=velocity;sourceBody.angularVelocity=angular;}Physics.simulationMode=mode;EditorApplication.isPaused=paused;}}
}
